import json,tarfile,shutil
from pathlib import Path
src=Path('build/column-probes');b=Path('build/column-fieldless-cloud');b.mkdir(exist_ok=True);(b/'jobs').mkdir(exist_ok=True)
old=Path('build/column-probes-cloud');selected={}
for name in ['jobs','walk-jobs']:
 js=[j for j in json.loads((old/(name+'.json')).read_text()) if j['grammar_name'] in {'css','html','go','tsx'} and j['size_class']=='small']
 (b/(name+'.json')).write_text(json.dumps(js,indent=2))
 for j in js:
  selected[j['name']]=['exact','control','fieldless']+(['super','fieldlesssuper'] if j['grammar_name'] in ['css','html'] else [])
  if name=='jobs':shutil.copy2(old/'jobs'/(j['name']+'.json'),b/'jobs')
(b/'job-variants.json').write_text(json.dumps(selected,indent=2))
shutil.copy2(src/'build-manifest.json',b/'build-manifest.json');shutil.copy2('tools/squatter/benchmark-kernel-probes.py',b)
with tarfile.open('build/column-fieldless-cloud.tar.gz','w:gz') as t:
 for p in b.rglob('*'):
  if p.is_file():t.add(p,arcname='column-fieldless-20260914/'+str(p.relative_to(b)))
 for v in ['exact','control','super','fieldless','fieldlesssuper']:
  for p in [1,0]:
   key=f'{v}-p{p}'
   for name in ['query-workload','walk','probe.patch']:t.add(src/'binaries'/key/name,arcname=f'column-fieldless-20260914/binaries/{key}/{name}')
